package com.company.tpm.security; import com.company.tpm.user.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.userdetails.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.stream.*;
@Service public class DatabaseUserDetailsService implements UserDetailsService { private final AppUserRepository users; public DatabaseUserDetailsService(AppUserRepository users){this.users=users;}
 @Override @Transactional(readOnly=true) public UserDetails loadUserByUsername(String username){var u=users.findByUsernameIgnoreCase(username).orElseThrow(()->new UsernameNotFoundException("Invalid credentials"));var authorities=Stream.concat(u.getRoles().stream().map(r->new SimpleGrantedAuthority("ROLE_"+r.getCode())),u.getRoles().stream().flatMap(r->r.getPermissions().stream()).map(p->new SimpleGrantedAuthority(p.getCode()))).distinct().toList();return User.withUsername(u.getUsername()).password(u.getPasswordHash()).disabled(!u.isEnabled()).credentialsExpired(u.isCredentialsExpired()).authorities(authorities).build();}
}
